begin;
create function pg_temp.email_assert(ok boolean,label text) returns void language plpgsql as $$begin if ok is distinct from true then raise exception 'FAIL %',label;end if;raise notice 'PASS %',label;end$$;
do $$declare req uuid:=gen_random_uuid();u uuid:=gen_random_uuid();j jsonb;l jsonb;r jsonb;lease uuid:=gen_random_uuid();begin
 perform public.slm_model_prepare();
 j:=public.slm_model_signup_begin(req,repeat('1',64),'MailFixture','','','fixture@slm.test');
 insert into auth.users(id,email,email_confirmed_at,raw_app_meta_data) values(u,j->>'auth_email',now(),jsonb_build_object('slm_signup_request',req));
 perform public.slm_model_signup_finish(req,repeat('1',64));
 insert into auth.sessions(id,user_id) values(u,u);perform public.slm_account_accept_session(u,u,1);
 l:=public.slm_email_issue(u,u,'verify','fixture@slm.test',gen_random_uuid(),repeat('2',64));
 perform pg_temp.email_assert(public.slm_model_resolve('fixture@slm.test') is null,'pending email cannot log in');
 begin perform public.slm_email_confirm((l->>'id')::uuid,repeat('3',64));raise exception 'wrong_token_accepted';exception when others then if sqlerrm<>'link_invalid' then raise;end if;end;
 perform pg_temp.email_assert((select email_login is null from public.slm_identity_registry where user_id=u),'wrong proof leaves alias unchanged');
 perform public.slm_email_confirm((l->>'id')::uuid,repeat('2',64));
 perform public.slm_email_confirm((l->>'id')::uuid,repeat('2',64));
 perform pg_temp.email_assert((public.slm_model_resolve('fixture@slm.test')->>'user_id')::uuid=u,'confirmation replay idempotently retains UUID');
 perform pg_temp.email_assert(slm_private.session_valid(u,u,false),'email confirmation preserves owner session');
 perform pg_temp.email_assert((select email=j->>'auth_email' from auth.users where id=u),'optional email never replaces internal Auth address');
 r:=public.slm_email_issue(u,null,'recovery','fixture@slm.test',gen_random_uuid(),repeat('4',64));
 begin perform public.slm_email_confirm((r->>'id')::uuid,repeat('4',64));raise exception 'wrong_kind_accepted';exception when others then if sqlerrm<>'link_invalid' then raise;end if;end;
 perform pg_temp.email_assert((select state='pending' from public.slm_email_links where id=(r->>'id')::uuid),'recovery token cannot confirm email');
 perform pg_temp.email_assert(public.slm_email_recovery_begin((r->>'id')::uuid,repeat('4',64),lease)=u,'recovery lease bound to exact account');
 perform pg_temp.email_assert(not slm_private.session_valid(u,u,false),'reset begin revokes old protected sessions');
 begin perform public.slm_email_recovery_begin((r->>'id')::uuid,repeat('4',64),gen_random_uuid());raise exception 'parallel_lease_accepted';exception when others then if sqlerrm<>'recovery_busy' then raise;end if;end;
 perform pg_temp.email_assert((select lease_id=lease from public.slm_email_links where id=(r->>'id')::uuid),'simultaneous retry cannot replace live lease');
 begin perform public.slm_email_recovery_finish((r->>'id')::uuid,repeat('4',64),gen_random_uuid());raise exception 'wrong_lease_accepted';exception when others then if sqlerrm<>'link_invalid' then raise;end if;end;
 perform pg_temp.email_assert((select operation_id is not null from public.slm_account_security where user_id=u),'wrong lease cannot finish pending reset');
 update public.slm_email_links set lease_until=clock_timestamp()-interval '1 second' where id=(r->>'id')::uuid;
 lease:=gen_random_uuid();perform public.slm_email_recovery_begin((r->>'id')::uuid,repeat('4',64),lease);
 perform public.slm_email_recovery_finish((r->>'id')::uuid,repeat('4',64),lease);
 perform pg_temp.email_assert((select operation_id is null and not must_change_password from public.slm_account_security where user_id=u),'interrupted reset can finish with replacement lease');
 begin perform public.slm_email_recovery_begin((r->>'id')::uuid,repeat('4',64),gen_random_uuid());raise exception 'used_link_accepted';exception when others then if sqlerrm<>'link_invalid' then raise;end if;end;
 perform pg_temp.email_assert((select state='consumed' from public.slm_email_links where id=(r->>'id')::uuid),'consumed recovery cannot be reused');
 insert into auth.sessions(id,user_id) values(req,u);perform public.slm_account_accept_session(u,req,2);
 l:=public.slm_email_issue(u,req,'verify','expired@slm.test',gen_random_uuid(),repeat('5',64));
 update public.slm_email_links set expires_at=clock_timestamp()-interval '1 second' where id=(l->>'id')::uuid;
 begin perform public.slm_email_confirm((l->>'id')::uuid,repeat('5',64));raise exception 'expired_accepted';exception when others then if sqlerrm<>'link_invalid' then raise;end if;end;
 perform pg_temp.email_assert((select email_login='fixture@slm.test' from public.slm_identity_registry where user_id=u),'expired verification preserves confirmed alias');
 perform pg_temp.email_assert(not has_table_privilege('authenticated','public.slm_email_links','select') and not has_table_privilege('anon','public.slm_email_links','select'),'RLS callback table private');
 perform pg_temp.email_assert(not has_function_privilege('authenticated','public.slm_email_confirm(uuid,text)','execute') and not has_function_privilege('anon','public.slm_email_recovery_begin(uuid,text,uuid)','execute'),'private RPCs cannot be called by clients');
 perform pg_temp.email_assert((select security_version=2 from public.slm_account_security where user_id=u),'reset increments security version once despite retry');
end$$;
do $$declare a uuid:=gen_random_uuid();b uuid:=gen_random_uuid();r uuid;u uuid;j jsonb;l1 jsonb;l2 jsonb;begin
 foreach u in array array[a,b] loop
  r:=gen_random_uuid();j:=public.slm_model_signup_begin(r,repeat('6',64),case when u=a then 'MailRaceA' else 'MailRaceB' end,'','');
  insert into auth.users(id,email,email_confirmed_at,raw_app_meta_data) values(u,j->>'auth_email',now(),jsonb_build_object('slm_signup_request',r));perform public.slm_model_signup_finish(r,repeat('6',64));insert into auth.sessions(id,user_id) values(u,u);perform public.slm_account_accept_session(u,u,1);
 end loop;
 l1:=public.slm_email_issue(a,a,'verify','race@slm.test',gen_random_uuid(),repeat('7',64));l2:=public.slm_email_issue(b,b,'verify','race@slm.test',gen_random_uuid(),repeat('8',64));
 perform public.slm_email_confirm((l1->>'id')::uuid,repeat('7',64));
 begin perform public.slm_email_confirm((l2->>'id')::uuid,repeat('8',64));raise exception 'duplicate_email_accepted';exception when unique_violation then null;end;
 perform pg_temp.email_assert((select count(*)=1 from public.slm_identity_registry where email_login='race@slm.test'),'competing confirmations retain global email uniqueness');
 perform pg_temp.email_assert((select email_login is null from public.slm_identity_registry where user_id=b) and slm_private.session_valid(b,b,false),'losing confirmation rolls back without losing session');
end$$;
rollback;
